1	package app;
2	
3	import model.*;
4	import view.*;
5	import config.Randomizer;
6	
7	import java.util.ArrayList;
8	import java.util.List;
9	import java.util.Random;
10	
11	
12	/**
13	 * The engine of the predator-prey simulation. It owns the field, the live
14	 * animals and plants, and drives the world forward one step at a time while
15	 * keeping the grid and graph views in sync.
16	 */
17	public class Simulator {
18	
19	
20		private static final int DEFAULT_WIDTH = 320;
21	
22		private static final int DEFAULT_DEPTH = 200;
23	
24		private static final TimeCycle DEFAULT_TIMECYCLE = TimeCycle.DAY;
25	
26		private static final Weather DEFAULT_WEATHER = Weather.SUN;
27	
28		private static final int TIMECYCLE_LENGTH = 4;
29	
30	
31		/** Supplies the animal and plant species used to populate the field. */
32		private final SpeciesRegistry registry;
33	
34		private final List<Animal> animals;
35	
36		private final List<Plant> plants;
37	
38		private final Field field;
39	
40		private int step;
41	
42		/** Every view observing the simulation; notified uniformly each step. */
43		private final List<SimulationView> views;
44	
45		/** Reused to test whether the simulation is still viable. */
46		private final FieldStats stats = new FieldStats();
47	
48		private TimeCycle currentTimeCycle;
49	
50		private final Climate climate;
51	
52		private int sickPercentage;
53	
54	
55		public Simulator(SpeciesRegistry registry) {
56			this(registry, DEFAULT_DEPTH, DEFAULT_WIDTH);
57		}
58	
59	
60		public Simulator(SpeciesRegistry registry, int depth, int width) {
61			if (width <= 0 || depth <= 0) {
62				System.out.println("The dimensions must be greater than zero.");
63				System.out.println("Using default values.");
64				depth = DEFAULT_DEPTH;
65				width = DEFAULT_WIDTH;
66			}
67	
68			this.registry = registry;
69			animals = new ArrayList<>();
70			plants = new ArrayList<>();
71			field = new Field(depth, width);
72			climate = new Climate(DEFAULT_WEATHER);
73			currentTimeCycle = DEFAULT_TIMECYCLE;
74	
75			views = List.of(
76					new SimulatorView(depth, width),
77					new GraphView(1000, 500, 500));
78	
79			reset();
80		}
81	
82	
83		public void runLongSimulation() {
84			simulate(4000);
85		}
86	
87	
88		public void simulate(int numSteps) {
89			for (int s = 1; s <= numSteps && isViable(); s++) {
90				simulateOneStep();
91				delay(60);
92			}
93		}
94	
95	
96		/** The simulation is viable while more than one species survives. */
97		private boolean isViable() {
98			stats.reset();
99			return stats.isViable(field);
100		}
101	
102	
103		public void simulateOneStep() {
104			step++;
105			climate.updateClimate(step);
106	
107			for (Plant plant : plants) {
108				plant.increaseStage(climate);
109			}
110	
111			List<Animal> newAnimals = new ArrayList<>();
112			for (Animal animal : animals) {
113				animal.act(newAnimals, currentTimeCycle);
114			}
115			animals.removeIf(animal -> !animal.isAlive());
116			animals.addAll(newAnimals);
117	
118			if (step % TIMECYCLE_LENGTH == 0) {
119				currentTimeCycle = currentTimeCycle.next();
120			}
121	
122			sickPercentage = computeSickPercentage();
123			publish();
124		}
125	
126	
127		/** Publish the current state to every view. */
128		private void publish() {
129			SimulationState state = new SimulationState(step, currentTimeCycle, field, climate, sickPercentage);
130			for (SimulationView view : views) {
131				view.showStatus(state);
132			}
133		}
134	
135	
136		private int computeSickPercentage() {
137			if (animals.isEmpty()) {
138				return 0;
139			}
140			int sick = 0;
141			for (Animal animal : animals) {
142				if (animal.isSick()) {
143					sick++;
144				}
145			}
146			return (sick * 100) / animals.size();
147		}
148	
149	
150		public void reset() {
151			step = 0;
152			animals.clear();
153			populate();
154			currentTimeCycle = TimeCycle.DAY;
155			climate.setCurrentWeather(Weather.SUN);
156	
157			sickPercentage = 0;
